export function landing(root){
root.innerHTML=`<div class="landing"><header class="lp-header"><a class="lp-logo" href="/"><span class="lp-mark">▶</span>Handover</a><nav><a href="#pricing">Pricing</a><a href="#features">Features</a><a href="#updates">Updates</a></nav><div class="lp-account"><a href="/workspace">Log in</a><a class="lp-dark" href="/workspace?record=1">Start recording</a></div></header><main><section class="lp-hero"><div class="lp-hero-inner"><div class="lp-cursor-stage" aria-hidden="true"><div class="lp-cursor tester" aria-hidden="true"><span class="lp-click-ripple"></span><svg width="20" height="20" viewBox="0 0 20 20" fill="none"><path d="M3 2L8.5 17.5L11.8 10.8L18.5 7.5L3 2Z" fill="currentColor" stroke="#FFFFFF" stroke-width="1.2" stroke-linejoin="round"/></svg><b>Tester</b></div><div class="lp-cursor developer" aria-hidden="true"><span class="lp-click-ripple"></span><svg width="20" height="20" viewBox="0 0 20 20" fill="none"><path d="M3 2L8.5 17.5L11.8 10.8L18.5 7.5L3 2Z" fill="currentColor" stroke="#FFFFFF" stroke-width="1.2" stroke-linejoin="round"/></svg><b>Developer</b></div><div class="lp-cursor manager" aria-hidden="true"><span class="lp-click-ripple"></span><svg width="20" height="20" viewBox="0 0 20 20" fill="none"><path d="M3 2L8.5 17.5L11.8 10.8L18.5 7.5L3 2Z" fill="currentColor" stroke="#FFFFFF" stroke-width="1.2" stroke-linejoin="round"/></svg><b>Product Manager</b></div></div><div class="lp-badge">FREE TO START <span>✳</span> NO CARD REQUIRED</div><div class="lp-title-group"><h1><span class="lp-title-line">Record <span class="lp-underline handover-phrase"><span class="lp-highlight" aria-hidden="true"></span><span class="lp-phrase">handover walkthroughs</span></span></span><span class="lp-title-line">&amp; <span class="lp-underline ai-phrase"><span class="lp-highlight" aria-hidden="true"></span><span class="lp-phrase">AI answers</span></span> your questions.</span></h1><p>Capture browser screens and actions so you can jump to the exact moment<br class="desktop-break"> something happened, even if you did it silently without saying a word.</p></div><div class="lp-actions"><a class="lp-dark" href="/workspace"><i aria-hidden="true">Ⅱ</i> Start recording free</a><a class="lp-secondary" href="#how-it-works">See how it works</a></div></div></section><section class="lp-product" id="how-it-works"><div class="lp-url">▢ <span>https://handover-studio.ashwatthama710.workers.dev/</span><i>♧</i></div><div class="lp-preview"><img class="lp-hero-screen" src="/handover-product-demo-poster.jpg" alt="Handover product walkthrough: actual app with synthetic sample content"><div class="lp-screen-glow"></div><button type="button" class="lp-preview-play" id="lp-tour-open" aria-label="Play the Handover product video">▶</button><div class="lp-preview-caption">See how Handover works <span>PRODUCT VIDEO · SYNTHETIC DEMO</span></div></div></section><section class="lp-ask"><h2>Try it yourself, ask about this build</h2><form id="lp-question-form"><input id="lp-question" aria-label="Ask about this build" placeholder="Ask a question about recording, editing or sharing..."><button aria-label="Ask question">↑</button></form><div id="lp-answer" aria-live="polite"></div><div class="lp-suggestions"><span>Try asking:</span><button data-question="How do I hide sensitive info?">“How do I hide sensitive info?”</button><button data-question="How do I share a recording?">“How do I share a recording?”</button><button data-question="Can I add a voice-over?">“Can I add a voice-over?”</button><button data-question="How do I invite my team?">“How do I invite my team?”</button></div></section><div class="lp-proof"><span>PRIVATE BY DEFAULT</span><span>SCREEN + DOM CAPTURE</span><span>NO SUBSCRIPTION</span></div><div class="lp-divider"></div><section class="lp-features" id="features"><h2>Go Beyond<br>Recording Walkthroughs</h2><div class="lp-motion-control"><button type="button" id="lp-motion-toggle" aria-pressed="false">Pause motion</button><span>Illustrative feature visuals</span></div><div class="lp-feature-grid">${cards()}</div></section><section class="lp-usecases"><h2>One clear handover.<br>Less back-and-forth.</h2><p class="lp-section-note">Ways to use Handover, not customer testimonials.</p><div class="lp-usecase-track" id="lp-usecase-track"><article><span>01 / CLIENT HANDOVERS</span><h3>Show the workflow.<br>Keep the context.</h3><p>Share a reviewed walkthrough instead of writing another long explanation.</p></article><article><span>02 / PRODUCT TEAMS</span><h3>Make the next step<br>easy to find.</h3><p>Attach timestamp notes and link the exact moment someone needs.</p></article><article><span>03 / INTERNAL GUIDES</span><h3>Record once.<br>Return when needed.</h3><p>Organize walkthroughs into projects, guides and collections.</p></article><article><span>04 / QA HANDOVERS</span><h3>Show what happened,<br>one action at a time.</h3><p>Replay captured browser interactions with searchable page text.</p></article></div><div class="lp-carousel-controls"><button id="lp-usecase-prev" aria-label="Previous use case">←</button><button id="lp-usecase-next" aria-label="Next use case">→</button></div></section><section class="lp-workflow" id="updates"><div><span class="lp-kicker">A CLEARER WAY TO HAND OVER</span><h2>One walkthrough.<br>All the context.</h2><p>Capture a browser workflow, review the timeline, then choose what to share. Find a captured screen by the words it contains.</p><a class="lp-dark" href="/workspace">Open your workspace →</a></div><div class="lp-step-list"><article><span>01</span><div><h3>Record your browser</h3><p>Capture screen video directly on desktop, or use the Chrome extension for page-text events.</p></div></article><article><span>02</span><div><h3>Review and edit</h3><p>Replay, add timestamp notes, skip sections and mask selected text.</p></div></article><article><span>03</span><div><h3>Share on your terms</h3><p>Create a viewer link when you are ready. Revoke it whenever you need.</p></div></article></div></section><section class="lp-pricing" id="pricing"><h2>Start free,<br>scale with your team</h2><div class="lp-pricing-notice"><strong>Free beta is live. Paid plans are coming soon.</strong><p>The plan allowances below are planned, not active entitlements. Current beta limits: 20 recordings, 12 MB per screen video, 18 MB per DOM timeline and shared free AI quota. No payment is collected.</p></div><div class="lp-pricing-grid"><article class="lp-pricing-card"><h3>FREE PLAN</h3><p class="lp-plan-audience">For trying Handover and personal test recordings.</p><div class="lp-price">₹0 <small>forever</small></div><p class="lp-plan-status">Planned plan allowances</p><ul><li><strong>3 Active Smart Demos</strong> (AI Voice &amp; Auto-Zoom)</li><li><strong>Unlimited Recordings</strong> (up to 15 min each)</li><li><strong>Unlimited Collections</strong> (Showcase hubs)</li><li><strong>Handover AI Assistant</strong> (3 Demos + 5 Recs/mo)</li><li><strong>Unlimited viewer members</strong> (Viewer role)</li><li><strong>Handover badge</strong> on public player</li></ul><a class="lp-dark" href="/workspace">Get started with free beta</a><p class="lp-card-caveat">Beta limits above apply today. Planned allowances are not enabled yet.</p></article><article class="lp-pricing-card lp-popular"><span class="lp-popular-badge">MOST POPULAR</span><h3>PRO PLAN</h3><p class="lp-plan-audience">For founders, product marketers, and teams creating recurring demos.</p><div class="lp-price">₹799 <small>per seat / month</small></div><p class="lp-plan-status">Coming soon · planned allowances</p><ul><li><strong>Unlimited Smart Demos &amp; Recordings</strong></li><li><strong>50 AI-Voiced Demos</strong> / seat / mo (BYOK unlocked)</li><li><strong>Up to 30 minutes</strong> per recording</li><li><strong>Unlimited Collections</strong> with custom branding</li><li><strong>Handover AI Assistant</strong> on all demos, recordings &amp; collections</li><li><strong>No Watermark</strong> (white-labeled player)</li><li><strong>Creator &amp; Admin roles</strong> (₹799/seat/month)</li></ul><button class="lp-dark" type="button" disabled>Pro coming soon</button><p class="lp-card-caveat">Not available to purchase. No subscription or charge.</p></article><article class="lp-pricing-card"><h3>ULTIMATE PLAN</h3><p class="lp-plan-audience">All-inclusive flat plan for growing teams. No per-seat math.</p><div class="lp-price">₹7,299 <small>per month, flat</small></div><p class="lp-plan-status">Coming soon · planned allowances</p><ul><li><strong>Unlimited Team Seats</strong> (Admins &amp; Creators at ₹0 extra)</li><li><strong>250 AI-Voiced Demos</strong> / mo (company pooled + BYOK)</li><li><strong>Unlimited Smart Demos &amp; Recordings</strong> (up to 30 mins)</li><li><strong>Unlimited Collections</strong> with Custom Domains</li><li><strong>Enterprise AI Assistant</strong> across all workspaces</li><li><strong>No Watermark</strong> + Priority AI processing</li></ul><button class="lp-dark" type="button" disabled>Ultimate coming soon</button><p class="lp-card-caveat">Not available to purchase. No subscription or charge.</p></article></div></section><section class="lp-faq" id="lp-faq"><h2>Answers to the<br>questions we<br>hear the most.</h2><div>${faq()}</div></section><section class="lp-last"><span class="lp-badge">RECORD ONCE. KEEP THE CONTEXT.</span><h2>Stop re-explaining the same walkthrough.</h2><div class="lp-actions"><a class="lp-dark" href="/workspace?record=1">Start recording free</a><a class="lp-secondary" href="/workspace">Get Chrome extension ↗</a></div></section></main><footer class="lp-footer lp-footer-reference"><div class="lp-logo"><span class="lp-mark">▶</span>Handover</div><p>Your browser walkthrough studio.</p><div class="lp-footer-columns"><section><h3>PRODUCT</h3><a href="#how-it-works">Product tour</a><a href="#features">Features</a><a href="#pricing">Plans &amp; pricing</a></section><section><h3>WORKSPACE</h3><a href="/workspace">Recordings</a><a href="/workspace">Projects & guides</a><a href="/workspace">Recorder setup</a></section><section><h3>LEARN</h3><a href="/faq">Questions & answers</a><a href="#updates">How it works</a><a href="/signup">Get started</a></section></div><small>Independent build. Not affiliated with Demoly. Features are still being built; see the coverage details in your workspace.</small></footer></div>`;
setupHeroMotion();
const reduce=matchMedia('(prefers-reduced-motion: reduce)');const motionButton=document.getElementById('lp-motion-toggle');motionButton.onclick=()=>{const paused=document.querySelector('.landing').classList.toggle('motion-paused');motionButton.setAttribute('aria-pressed',String(paused));motionButton.textContent=paused?'Resume motion':'Pause motion';};if(reduce.matches){motionButton.hidden=true;motionButton.nextElementSibling.textContent='Motion reduced by your device preference';}
const tourScenes=[['SCREEN RECORDING','Your screen. Your voice.','Choose a screen, window or tab on a supported desktop browser. Include your microphone when you need it. Review the video before upload.','Screen video · maximum 12 MB','▣'],['BROWSER WALKTHROUGH','Click through. Keep the context.','Use the Chrome DOM recorder for browser events and searchable page text. Input values are masked during capture. Review before sharing.','DOM timeline · maximum 18 MB','☷'],['REVIEW YOUR RECORDING','Make every moment easier to find.','Add timestamp notes. For DOM walkthroughs, skip time ranges and redact selected text nodes. Pixel blur and video trimming are not released.','Review → Notes → Share','✂'],['SHARE WITH INTENT','A link when you are ready.','Recordings start private. Create a public viewer link explicitly, and revoke it when you need. Anyone with an active link can view the shared recording.','Private by default','↗']];
for(const card of document.querySelectorAll('.lp-feature')){card.addEventListener('pointermove',e=>{const r=card.getBoundingClientRect();card.querySelector('.fv')?.setAttribute('data-active','true');card.style.setProperty('--mx',(e.clientX-r.left)/r.width);card.style.setProperty('--my',(e.clientY-r.top)/r.height);const visual=card.querySelector('.fv');if(visual){visual.style.setProperty('--p',(e.clientX-r.left)/r.width);visual.style.setProperty('--py',(e.clientY-r.top)/r.height);}});card.addEventListener('pointerleave',()=>{card.querySelector('.fv')?.setAttribute('data-active','false');card.querySelector('.fv')?.setAttribute('data-active','true');card.style.setProperty('--mx','.5');card.style.setProperty('--my','.5');});}
function openTour(){const modal=document.createElement('div');modal.className='lp-tour-backdrop';modal.innerHTML='<section class="lp-tour-dialog lp-video-dialog" role="dialog" aria-modal="true" aria-label="Handover product video"><button class="lp-tour-close" aria-label="Close product video">×</button><video id="lp-product-video" controls playsinline preload="metadata" poster="/handover-product-demo-poster.jpg"><source src="/handover-product-demo.mp4" type="video/mp4"><track kind="captions" src="/handover-product-demo.vtt" srclang="en" label="English"></video><p class="lp-tour-disclosure">Actual Handover app with synthetic demo content. Edited product video.</p><a href="/handover-product-demo.mp4" download>Download product video</a></section>';document.body.append(modal);const previousFocus=document.activeElement,video=modal.querySelector('video');const close=()=>{video.pause();modal.remove();document.removeEventListener('keydown',key);previousFocus?.focus()};const key=e=>{if(e.key==='Escape')close();if(e.key==='Tab'){const focusable=[...modal.querySelectorAll('button,a,video')];if(e.shiftKey&&document.activeElement===focusable[0]){e.preventDefault();focusable.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===focusable.at(-1)){e.preventDefault();focusable[0].focus()}}};modal.querySelector('.lp-tour-close').onclick=close;modal.onclick=e=>{if(e.target===modal)close()};document.addEventListener('keydown',key);modal.querySelector('.lp-tour-close').focus();video.play().catch(()=>{});}
document.getElementById('lp-tour-open').onclick=openTour;for(const [id,direction] of [['lp-usecase-prev',-1],['lp-usecase-next',1]])document.getElementById(id).onclick=()=>{const track=document.getElementById('lp-usecase-track');track.scrollBy({left:direction*(track.querySelector('article').getBoundingClientRect().width+18),behavior:'instant'});};
function answer(q){let s=q.toLowerCase();if(/price|free|cost|limit/.test(s))return 'Free beta is available. Planned Pro is ₹799 per seat/month and Ultimate is ₹7,299 per month flat. Paid plans are coming soon, with no checkout or active paid entitlements. Current free beta limits are20 recordings,12 MB per screen video and18 MB per DOM timeline. AI uses the shared free allowance; exact text search remains available when that quota is exhausted.';if(/voice|audio|microphone/.test(s))return 'Smart steps can be drafted with real AI, edited and read aloud using your device’s browser voice. This is not an exported AI voiceover track. Desktop screen recording can include microphone audio. Available browser speech recognition can draft transcript text; review it before saving. Tab audio depends on the capture/browser support.';if(/team|invite|role/.test(s))return 'This beta currently has individual account workspaces. Team invites and Admin/Editor/Viewer roles are not ready yet. No invitation is sent from this page.';if(/sensitive|hide|blur|mask|privacy/.test(s))return 'Inputs are masked during capture. The editor can redact selected captured text nodes. Dynamic visual masking is not ready. Review every screen before sharing and do not record sensitive customer data yet.';if(/share|embed|client/.test(s))return 'Recordings start private. Open one in your workspace, choose Share / embed and explicitly create a public viewer link. You can revoke that link. Anyone with an active public link can watch and search the sanitized replay.';if(/record|chrome|start|install/.test(s))return 'Open the workspace, sign in and choose New recording. On a supported desktop browser, choose your screen and start directly. For silent DOM/text capture, the Chrome extension remains available from Settings. Phone screen capture is not supported.';if(/price|free|cost/.test(s))return 'There is no subscription or paid checkout. The beta build uses existing free allowances, with 20 recordings, a 12 MB screen-video limit and an 18 MB DOM-timeline limit. AI can be unavailable when its shared quota is exhausted; text search remains available.';return 'This preview has a real browser capture/replay foundation, text search, folders, edits and explicit sharing. Saved AI narration, advanced video edits, team features and full reference parity are still being built. This answer is a local feature guide, not an AI response about a recording.';}
const show=q=>{const el=document.getElementById('lp-answer');el.textContent=answer(q);el.classList.add('visible');document.getElementById('lp-question').value=q};document.getElementById('lp-question-form').onsubmit=e=>{e.preventDefault();show(document.getElementById('lp-question').value)};document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>show(b.dataset.question));}
function cards(){const a=[['Embed Anywhere','</>','Share a player in your own page.','Ready','embed'],['Record Your Browser','REC','Screen video or searchable DOM capture.','Ready','record'],['AI Voiceovers','0:03','Turn steps into narrated walkthroughs.','In progress','voice'],['Share a Walkthrough','↗','Create and revoke public viewer links.','Ready','share'],['Timestamp Notes','✎','Leave context at the moment it matters.','Ready','notes'],['Trim DOM Timelines','✂','Skip unwanted DOM replay sections.','Ready','trim'],['Knowledge Library','▤','Keep walkthroughs in one place.','Ready','library'],['Hide Sensitive Text','▧','Mask selected captured text nodes.','Partial','mask'],['Search Captured Screens','⌕','Find text with exact timeline links.','Ready','search'],['Bug Diagnostics','⌘','Recording-linked bug reporting.','Planned','bug'],['Edit After Sharing','↻','Update a replay without changing its link.','Ready','edit'],['Ask Your Recording','✳','Text evidence search; optional free AI.','Partial','ai'],['Project Folders','▱','Organize recordings by project.','Ready','folder'],['Smart Demos','⊙','Author steps and draft them with AI.','Partial','zoom'],['Team Collaboration','♧','Invitations and role-based access.','Not ready','team']];return a.map(([t,i,d,status,c])=>`<article class="lp-feature ${c}"><div class="lp-feature-art" aria-hidden="true">${illustration(c)}${miniPanel(c)}<span>${i.replace(/</g,'&lt;').replace(/>/g,'&gt;')}</span>${c==='trim'?'<div class="lp-timeline"><i></i></div>':c==='mask'?'<div class="lp-mask-lines">Email <b>••••••••••</b><br>API key <b>••••••••••</b></div>':c==='search'?'<div class="lp-result">billing settings <b>02:14</b></div>':c==='share'?'<div class="lp-link">handover / walkthrough <b>Copy</b></div>':c==='record'?'<div class="lp-recording">● CAPTURE YOUR BROWSER</div>':''}</div><div class="lp-feature-copy"><h3>${t}</h3><p>${d}</p><small class="${status==='Ready'?'ready':'pending'}">${status}</small></div></article>`).join('')}
function faq(){return [['What is this workspace?','A browser walkthrough recorder and searchable handover library, based on the reference layout. It is an independent build, not Demoly or an affiliated service.'],['Is this the complete reference product yet?','No. Capture/replay, library, folders, basic timeline edits and sharing are working foundations. Audio indexing, advanced smart demos, team access, visual reasoning and other modules remain open.'],['Can I ask questions about a recording?','You can search captured screen text and jump to matching timestamps. Optional AI uses the existing shared free quota; if it is unavailable, exact text evidence search still works.'],['Can I hide sensitive information?','Input values are masked during capture, and selected text nodes can be redacted in the editor. Dynamic visual redaction is not finished. Do not record sensitive customer information yet.'],['Does the front page need a password?','No. This front page is open. Your private recordings and workspace remain behind sign-in, so the public page does not expose them.'],['Is it free to use?','There is no paid plan or checkout. Existing free hosting/AI limits apply. Current limits are 20 recordings, 12 MB per screen video and 18 MB per DOM timeline.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}

