// Hero pointer choreography follows the observed reference cycle. Coordinates are
// measured from the actual Handover words so different copy stays aligned.
function setupHeroMotion(){
const hero=document.querySelector('.lp-hero'),stage=hero.querySelector('.lp-cursor-stage'),tester=stage.querySelector('.tester'),developer=stage.querySelector('.developer'),ai=hero.querySelector('.ai-phrase'),handover=hero.querySelector('.handover-phrase'),reduce=matchMedia('(prefers-reduced-motion: reduce)'),desktop=matchMedia('(min-width:1024px)');let animations=[],timer;
const ease=(kind)=>{const values=Array.from({length:41},(_,i)=>{const t=i/40;return kind==='in'?t*t:kind==='out'?1-(1-t)**2:kind==='cubicOut'?1-(1-t)**3:kind==='back'?1+(2.5*(t-1)**3+1.5*(t-1)**2):t<.5?2*t*t:1-(-2*t+2)**2/2});return 'linear('+values.join(',')+')'};
function build(){animations.forEach(a=>a.cancel());animations=[];if(reduce.matches||!desktop.matches)return;tester.style.transform='none';developer.style.transform='none';const total=10.07;
const frame=(time,x=0,y=0,scale=1,e='linear')=>({offset:time/total,transform:`translate(${x}px,${y}px) scale(${scale})`,easing:e});
function motion(el,word,start,reverse){const c=el.getBoundingClientRect(),w=word.getBoundingClientRect(),y=w.top+w.height*.55-(c.top+2),left=w.left-(c.left+3),right=w.right-(c.left+3),begin=reverse?right:left,end=reverse?left:right,drag=reverse?1.05:.85,move=start+1.2,clickEnd=move+.35,dragStart=clickEnd+.08+.04,dragEnd=dragStart+drag,backStart=dragEnd+.14+.2,backEnd=backStart+1.3,fadeEnd=backEnd+.35;
let keys=[frame(0),frame(start,0,0,1,ease('in')),frame(start+.6,reverse?begin+30:.45*begin-20,reverse?.5*y+20:.5*y-25,1,ease('out')),frame(move,begin,y,1,ease('in')),frame(move+.09,begin,y,.84),frame(clickEnd,begin,y,.84,ease('out')),frame(clickEnd+.08,begin,y,.92),frame(dragStart,begin,y,.92,ease('inOut')),frame(dragEnd,end,y,.92,ease('back')),frame(dragEnd+.14,end,y),frame(backStart,end,y,1,ease('in')),frame(backStart+.65,reverse?.5*end:.55*end-15,reverse?.4*y+25:.45*y-20,1,ease('cubicOut')),frame(backEnd),frame(total)];
if(start===0)keys.splice(0,1);animations.push(el.animate(keys,{duration:total*1000,iterations:Infinity}));
const highlight=word.querySelector('.lp-highlight'),hidden=reverse?'inset(0% 0% 0% 100%)':'inset(0% 100% 0% 0%)';animations.push(highlight.animate([{offset:0,clipPath:hidden,opacity:1},{offset:dragStart/total,clipPath:hidden,opacity:1,easing:ease('inOut')},{offset:dragEnd/total,clipPath:'inset(0% 0% 0% 0%)',opacity:1},{offset:backEnd/total,clipPath:'inset(0% 0% 0% 0%)',opacity:1,easing:ease('out')},{offset:fadeEnd/total,clipPath:'inset(0% 0% 0% 0%)',opacity:0},{offset:Math.min(1,(fadeEnd+.001)/total),clipPath:hidden,opacity:1},{offset:1,clipPath:hidden,opacity:1}],{duration:total*1000,iterations:Infinity}));
animations.push(el.querySelector('.lp-click-ripple').animate([{offset:0,transform:'scale(0)',opacity:0},{offset:move/total,transform:'scale(.2)',opacity:.65,easing:ease('cubicOut')},{offset:clickEnd/total,transform:'scale(1.6)',opacity:0},{offset:1,transform:'scale(1.6)',opacity:0}],{duration:total*1000,iterations:Infinity}));}
motion(tester,ai,0,false);motion(developer,handover,4.86,true);sync();}
function sync(){const paused=document.querySelector('.landing').classList.contains('motion-paused');animations.forEach(a=>paused?a.pause():a.play())}
new MutationObserver(sync).observe(document.querySelector('.landing'),{attributes:true,attributeFilter:['class']});reduce.addEventListener('change',build);desktop.addEventListener('change',build);window.addEventListener('resize',()=>{clearTimeout(timer);timer=setTimeout(build,200)});document.fonts.ready.then(async()=>{await Promise.allSettled([...hero.querySelectorAll('.lp-title-line')].flatMap(el=>el.getAnimations().map(a=>a.finished)));build()});
}
